<?php require_once __DIR__.'/auth.php'; $title='Messages'; include 'admin-head.php'; include 'sidebar.php'; include 'topbar.php'; ?><main class="main"><?php $items=read_data('messages');if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='delete'){$id=(int)$_POST['id'];$items=array_values(array_filter($items,fn($x)=>(int)$x['id']!==$id));}else{$id=(int)$_POST['id'];foreach($items as &$x)if((int)$x['id']===$id)$x['status']='Read';unset($x);}write_data('messages',$items);redirect('messages.php');}?>
<div class="row g-3"><?php foreach(array_reverse($items) as $m): ?><div class="col-md-6"><div class="card shadow-sm p-4 h-100"><div class="d-flex justify-content-between"><div><h5 class="fw-bold mb-1"><?=e($m['subject'])?></h5><small class="text-muted"><?=e($m['name'])?> · <?=e($m['email'])?></small></div><span class="badge <?=$m['status']==='Unread'?'bg-warning text-dark':'bg-success'?>"><?=e($m['status'])?></span></div><hr><p style="white-space:pre-wrap"><?=e($m['message'])?></p><div class="mt-auto"><form method="post" class="d-inline"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-sm btn-outline-success"><?= $m['status']==='Unread'?'Mark Read':'Read' ?></button></form><form method="post" class="d-inline" onsubmit="return confirm('Delete message?')"><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></div></div><?php endforeach;?><?php if(!$items): ?><div class="col-12 text-center text-muted py-5">No messages.</div><?php endif;?></div><?php include 'admin-foot.php'; ?>